        <div class="soft-card vet-form-card vet-entry-card" id="prescriptionFormPanel" <?=(!empty($consultationEntry)||$appointmentFocus>0)?'':'hidden'?>>
            <div class="vet-form-title clinical-form-title"><span class="pet-icon"><?=ui_icon('plus')?></span><div><h3><?=!empty($consultationEntry)?'Add Consultation':'Add Prescription'?></h3></div></div>
            <?php if($consultationError): ?><div class="alert alert-danger" role="alert"><?=e($consultationError)?></div><?php endif; ?>
            <?php if($linkedAppointment && !$consultationBlocked): ?><p class="field-help">Appointment #<?=intval($appointmentFocus)?> &middot; <?=e($linkedAppointment['pet_name'])?> &middot; Completed visit</p><?php endif; ?>
            <?php if($appointmentFocus && ($_SESSION['role']??'')==='admin'): ?><a class="button-secondary" href="<?=app_url('admin/appointments.php?appointment_id='.$appointmentFocus)?>">Back to appointment</a><?php endif; ?>
            <form method="POST">
                <?= csrf_field() ?>
                <input type="hidden" name="appointment_id" value="<?=$appointmentFocus?>">
                <label class="form-label fw-bold mb-1" for="consultationPet">Pet</label>
                <?php if($appointmentFocus): ?>
                <input type="hidden" name="pet_id" value="<?=intval($petPrefill)?>">
                <input class="form-control" id="consultationPet" value="<?=e($linkedAppointment['pet_name']??'Appointment unavailable')?>" readonly>
                <?php else: ?>
                <select class="form-select" id="consultationPet" name="pet_id" required><option value="">Choose a pet</option><?php $consultationPetOptions=$conn->query("SELECT id,name FROM pets WHERE verification_status='approved' ORDER BY name"); while($p=$consultationPetOptions->fetch_assoc()): ?><option value="<?=$p['id']?>" <?=$petPrefill===(int)$p['id']?'selected':''?>><?=e($p['name'])?></option><?php endwhile;?></select>
                <?php endif; ?>
                <label class="form-label fw-bold mb-1">Veterinarian</label><input class="form-control" value="<?=e($vetName)?>" readonly><small class="field-help">Current logged-in clinic user</small>
                <label class="form-label fw-bold mb-1" for="consultationDate">Visit Date</label><input class="form-control" id="consultationDate" type="date" name="visit_date" value="<?=e($consultationValues['visit_date'])?>" required><div class="field-help">Prefilled from the linked visit when available. Use the actual consultation date.</div>
                <label class="form-label fw-bold mb-1" for="consultationDiagnosis">Diagnosis</label><input class="form-control" id="consultationDiagnosis" name="diagnosis" list="recordDiagnosisSuggestions" placeholder="Diagnosis" value="<?=e($consultationValues['diagnosis'])?>">
                <label class="form-label fw-bold mb-1" for="consultationTreatment">Treatment</label><input class="form-control" id="consultationTreatment" name="treatment" list="recordTreatmentSuggestions" placeholder="Treatment" value="<?=e($consultationValues['treatment'])?>">
                <label class="form-label fw-bold mb-1" for="consultationNoteType">Note type</label><select class="form-select" name="note_type" id="consultationNoteType"><?php foreach(['neutral'=>'General note','positive'=>'Improving / stable','negative'=>'Urgent concern','follow_up'=>'Needs follow-up'] as $key=>$label):?><option value="<?=e($key)?>" <?=$consultationValues['note_type']===$key?'selected':''?>><?=e($label)?></option><?php endforeach;?></select><label class="form-label fw-bold mb-1" for="consultationNotes">Notes</label><input class="form-control" id="consultationNotes" name="notes" list="recordNotesSuggestions" placeholder="Clinical note" value="<?=e($consultationValues['notes'])?>">
                <datalist id="recordDiagnosisSuggestions"><?php foreach(['Gastroenteritis','Allergic dermatitis','Otitis externa (ear infection)','Upper respiratory infection','Urinary tract infection','Dental disease','Intestinal parasites','Flea infestation','Canine parvovirus infection','Feline upper respiratory infection'] as $commonDiagnosis):?><option value="<?=e($commonDiagnosis)?>"><?php endforeach;?><?php $suggest=$conn->query("SELECT DISTINCT diagnosis value FROM medical_records WHERE TRIM(COALESCE(diagnosis,''))<>'' ORDER BY id DESC LIMIT 40");while($x=$suggest->fetch_assoc()):?><option value="<?=e($x['value'])?>"><?php endwhile;?></datalist><datalist id="recordTreatmentSuggestions"><?php $suggest=$conn->query("SELECT DISTINCT treatment value FROM medical_records WHERE TRIM(COALESCE(treatment,''))<>'' ORDER BY id DESC LIMIT 40");while($x=$suggest->fetch_assoc()):?><option value="<?=e($x['value'])?>"><?php endwhile;?></datalist><datalist id="recordPrescriptionSuggestions"><?php $suggest=$conn->query("SELECT DISTINCT prescription value FROM medical_records WHERE TRIM(COALESCE(prescription,''))<>'' ORDER BY id DESC LIMIT 40");while($x=$suggest->fetch_assoc()):?><option value="<?=e($x['value'])?>"><?php endwhile;?></datalist><datalist id="recordNotesSuggestions"><?php $suggest=$conn->query("SELECT DISTINCT notes value FROM medical_records WHERE TRIM(COALESCE(notes,''))<>'' ORDER BY id DESC LIMIT 40");while($x=$suggest->fetch_assoc()): $cleanSuggestion=medical_note_text((string)$x['value']); if($cleanSuggestion==='') continue;?><option value="<?=e($cleanSuggestion)?>"><?php endwhile;?></datalist><button class="btn btn-primary w-100 mt-2" <?= $consultationBlocked ? 'disabled' : '' ?>>Save consultation</button>
                <?php if(!empty($consultationEntry)):?><a class="button-secondary mt-2" href="<?=e($consultationListReturn!==''?app_url($consultationListReturn):'medical_records.php')?>">Cancel</a><?php else:?><button class="button-secondary mt-2" type="button" id="prescriptionFormClose">Close form</button><?php endif;?>
            </form>
        </div>
